<?php
declare(strict_types=1);

/**
 * REG.RU shared hosting admin gateway. Password is never passed in an HTTP
 * Authorization header: some hosting proxies drop that header before PHP.
 * Every HTML/CSS/JS asset is served only after a verified PHP session.
 */
header('X-Robots-Tag: noindex, nofollow', true);
header('X-Content-Type-Options: nosniff', true);
header('Referrer-Policy: no-referrer', true);
header('Cache-Control: private, no-store', true);
header('Content-Security-Policy: frame-ancestors \'none\'', true);

$private = '/var/www/u3728035/data/wedding-private';
$usersPath = $private.'/.htpasswd';
$sessionDir = $private.'/admin-sessions';
if (!is_dir($sessionDir) && !@mkdir($sessionDir, 0700, true) && !is_dir($sessionDir)) {
    http_response_code(503);
    exit('Administrative session storage unavailable');
}
ini_set('session.save_path', $sessionDir);
// Keep PHP's session garbage collection in sync with the 12-hour admin idle timeout.
ini_set('session.gc_maxlifetime', '43200');
ini_set('session.use_strict_mode', '1');
ini_set('session.use_only_cookies', '1');
ini_set('session.cookie_httponly', '1');
ini_set('session.cookie_secure', '1');
ini_set('session.cookie_samesite', 'Lax');
session_name('wedding_admin');
session_set_cookie_params([
    'lifetime' => 0, 'path' => '/admin', 'secure' => true,
    'httponly' => true, 'samesite' => 'Lax'
]);
session_start();
if (empty($_SESSION['csrf'])) {
    $_SESSION['csrf'] = bin2hex(random_bytes(24));
}
// An already-open login tab may outlive its PHP session. Let the same-origin
// form retrieve a fresh token immediately before posting, without weakening
// CSRF enforcement on login or on authenticated data changes.
if (($_SERVER['REQUEST_METHOD'] ?? 'GET') === 'GET' &&
    isset($_GET['refresh_login_csrf'])) {
    header('Content-Type: application/json; charset=UTF-8', true);
    echo json_encode(['ok'=>true, 'csrf'=>(string)$_SESSION['csrf']],
      JSON_THROW_ON_ERROR);
    exit;
}

$rows = @file($usersPath, FILE_IGNORE_NEW_LINES | FILE_SKIP_EMPTY_LINES);
$users = [];
if (is_array($rows)) {
    foreach ($rows as $row) {
        $pair = explode(':', $row, 2);
        if (count($pair) === 2 && preg_match('/^[a-z][a-z0-9_-]{3,40}$/i', $pair[0])) {
            $users[$pair[0]] = $pair[1];
        }
    }
}
function adminEscape(string $text): string {
    return htmlspecialchars($text, ENT_QUOTES | ENT_SUBSTITUTE, 'UTF-8');
}
function adminCsrfValid(): bool {
    return isset($_POST['csrf']) && is_string($_POST['csrf']) &&
        hash_equals((string)($_SESSION['csrf'] ?? ''), $_POST['csrf']);
}
if (($_SERVER['REQUEST_METHOD'] ?? 'GET') === 'POST' && isset($_POST['logout'])) {
    if (adminCsrfValid()) {
        $_SESSION = [];
        session_regenerate_id(true);
    }
    header('Location: /admin/', true, 303);
    exit;
}

$loginError = '';
if (($_SERVER['REQUEST_METHOD'] ?? 'GET') === 'POST' && isset($_POST['login'])) {
    $attempts = (int)($_SESSION['attempts'] ?? 0);
    $since = (int)($_SESSION['attempt_start'] ?? 0);
    if (time() - $since > 900) {
        $attempts = 0;
        $_SESSION['attempt_start'] = time();
    }
    if ($attempts >= 8) {
        http_response_code(429);
        $loginError = 'Слишком много попыток. Повторите позже.';
    } elseif (!adminCsrfValid()) {
        http_response_code(403);
        $loginError = 'Страница устарела. Обновите её и попробуйте ещё раз.';
    } else {
        $user = substr(trim((string)($_POST['username'] ?? '')), 0, 100);
        $password = (string)($_POST['password'] ?? '');
        $hash = $users[$user] ?? '';
        if ($hash !== '' && strlen($password) <= 512 && password_verify($password, $hash)) {
            session_regenerate_id(true);
            $_SESSION['admin_login'] = $user;
            $_SESSION['admin_stamp'] = hash('sha256', $hash);
            $_SESSION['last_seen'] = time();
            $_SESSION['attempts'] = 0;
            header('Location: /admin/', true, 303);
            exit;
        }
        $_SESSION['attempts'] = $attempts + 1;
        http_response_code(401);
        $loginError = 'Неверный логин или пароль.';
    }
}

$login = (string)($_SESSION['admin_login'] ?? '');
$valid = $login !== '' && isset($users[$login]) &&
    hash_equals(hash('sha256', $users[$login]), (string)($_SESSION['admin_stamp'] ?? '')) &&
    time() - (int)($_SESSION['last_seen'] ?? 0) <= 12 * 3600;
if (!$valid) {
    unset($_SESSION['admin_login'], $_SESSION['admin_stamp']);
    if (isset($_GET['api'])) {
        http_response_code(401);
        header('Content-Type: application/json; charset=UTF-8', true);
        echo '{"ok":false,"error":"login_required"}';
        exit;
    }
    if (isset($_GET['asset'])) {
        http_response_code(401);
        header('Content-Type: text/plain; charset=UTF-8', true);
        exit('Authentication required');
    }
    header('Content-Type: text/html; charset=UTF-8', true);
    $csrf = adminEscape((string)$_SESSION['csrf']);
    $error = adminEscape($loginError);
    echo '<!doctype html><html lang="ru"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width, initial-scale=1">';
    echo '<meta name="robots" content="noindex,nofollow"><meta name="color-scheme" content="only light"><title>Вход — Никита и Кристина</title>';
    echo '<style>:root{color-scheme:only light;--login-green:#194b30;--login-text:#1b1b1b;--login-art:url("data:image/webp;base64,")}*,*:before,*:after{box-sizing:border-box}html{background:#f4f7f2}body{margin:0;min-height:100vh;min-height:100svh;display:grid;place-items:center;padding:24px;background:#f4f7f2;color:var(--login-text);font:16px/1.5 system-ui,Arial,sans-serif}main.login-screen{isolation:isolate;position:relative;display:flex;flex-direction:column;width:min(100%,450px);min-height:740px;background:#fff;border-radius:24px;box-shadow:0 12px 48px #173b2414;overflow:hidden}.login-art-top,.login-art-bottom{flex:none;background-image:var(--login-art);background-repeat:no-repeat;background-size:100% auto;pointer-events:none}.login-art-top{height:clamp(180px,25vh,230px);background-position:center top}.login-art-bottom{height:clamp(130px,19vh,175px);background-position:center bottom;margin-top:auto}.login-content{padding:4px 30px 12px;position:relative;z-index:1;flex:1;display:flex;flex-direction:column;justify-content:center}.login-heading{text-align:center;font:400 clamp(36px,5vw,44px)/1.07 Georgia,serif;margin:0 0 12px;letter-spacing:-.035em}.login-ornament{width:96px;height:28px;display:block;margin:0 auto 11px;color:#507c38}.login-caption{text-align:center;font-size:16px;line-height:1.5;margin:0 0 23px;color:#33453a}.login-form{display:grid;gap:12px}.login-field{position:relative;display:flex;align-items:center;min-height:52px;border:1px solid #dce6dc;border-radius:11px;background:#fff;gap:12px;padding:0 13px}.login-field:focus-within{border-color:#194b30;box-shadow:0 0 0 2px #194b301f}.login-field svg{width:23px;height:23px;flex:none;fill:none;stroke:#194b30;stroke-width:1.8;stroke-linecap:round;stroke-linejoin:round}.login-field input{min-width:0;width:100%;border:0;outline:0;background:#fff;color:#1b1b1b;min-height:50px;font:inherit;padding:10px 0}.login-field input::placeholder{color:#657369}.login-field input:-webkit-autofill{-webkit-box-shadow:0 0 0 1000px #fff inset;-webkit-text-fill-color:#1b1b1b;caret-color:#1b1b1b}.login-field .password-toggle{flex:none;border:0;background:none;color:#194b30;display:grid;place-items:center;width:36px;height:44px;padding:0;cursor:pointer}.login-submit{border:0;background:#194b30;color:#fff;border-radius:11px;width:100%;min-height:52px;padding:12px;font:600 22px/1.2 Georgia,serif;cursor:pointer;margin-top:7px}.login-submit:hover{background:#28613f}.login-submit:disabled{opacity:.65}.login-submit:focus-visible,.password-toggle:focus-visible{outline:2px solid #194b30;outline-offset:3px}.error{color:#c32232;font-size:16px;text-align:center;margin:0 0 12px}.sr-only{position:absolute;width:1px;height:1px;padding:0;margin:-1px;overflow:hidden;clip:rect(0,0,0,0);white-space:nowrap;border:0}@media(max-width:500px){html,body{background:#fff}body{padding:0;display:block}main.login-screen{width:100%;min-height:100svh;border-radius:0;box-shadow:none}.login-content{padding:4px 24px 14px}.login-art-top{height:clamp(160px,27svh,255px)}.login-art-bottom{height:clamp(115px,18svh,185px)}}@media(max-height:700px){.login-art-top{height:150px}.login-art-bottom{height:100px}main.login-screen{min-height:0}.login-content{padding-top:8px;padding-bottom:14px}.login-heading{font-size:36px}.login-caption{margin-bottom:16px}}</style>';
    echo '</head><body><main class="login-screen"><div class="login-art-top" aria-hidden="true"></div><div class="login-content"><h1 class="login-heading">Никита<br>и Кристина</h1><svg class="login-ornament" viewBox="0 0 100 28" aria-hidden="true"><path d="M3 20 Q48 6 96 16 M18 15 Q29 9 43 11 M48 12 Q61 20 78 19" fill="none" stroke="currentColor" stroke-width="1.5"/><path d="M28 12 Q39 1 50 8 Q45 17 28 12 M52 12 Q67 5 74 12 Q68 20 52 12 M48 15 Q55 25 68 23 Q61 14 48 15" fill="currentColor"/></svg><p class="login-caption">Система организации свадьбы</p>';
    if ($error !== '') echo '<p class="error" role="alert">'.$error.'</p>';
    echo '<form class="login-form" method="post" action="/admin/" autocomplete="on"><input type="hidden" name="csrf" value="'.$csrf.'">';
    echo '<input type="hidden" name="login" value="1"><label class="login-field"><svg viewBox="0 0 24 24" aria-hidden="true"><circle cx="12" cy="8" r="4"/><path d="M4 21v-2a8 8 0 0 1 16 0v2"/></svg><span class="sr-only">Логин</span><input name="username" value="wedding-admin" autocomplete="username" placeholder="Логин" required maxlength="100"></label>';
    echo '<div class="login-field"><svg viewBox="0 0 24 24" aria-hidden="true"><rect x="4" y="10" width="16" height="11" rx="2"/><path d="M8 10V7a4 4 0 0 1 8 0v3M12 14v3"/></svg><label for="login-password" class="sr-only">Пароль</label><input id="login-password" name="password" type="password" autocomplete="current-password" placeholder="Пароль" required maxlength="512"><button type="button" class="password-toggle" aria-label="Показать пароль" aria-pressed="false"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M2 12s4-7 10-7 10 7 10 7-4 7-10 7S2 12 2 12Z"/><circle cx="12" cy="12" r="3"/><path class="eye-slash" d="M3 3l18 18"/></svg></button></div>';
    echo '<button type="submit" class="login-submit">Войти</button></form>';
    // Prevent a long-idle mobile tab from submitting an expired session token.
    // If the preflight fails, a standard HTML form submission still works.
    echo '<script>(function(){const f=document.querySelector("form");let busy=false;f.addEventListener("submit",async function(e){if(busy)return;e.preventDefault();busy=true;const b=f.querySelector("button[type=submit]");b.disabled=true;try{const r=await fetch("/admin/?refresh_login_csrf=1",{credentials:"same-origin",cache:"no-store",headers:{"Accept":"application/json"}});if(r.ok){const x=await r.json();if(x&&typeof x.csrf==="string"&&/^[a-f0-9]{48}$/.test(x.csrf))f.elements.csrf.value=x.csrf;}}catch(_e){}f.submit();});})();</script>';
    echo '<script>(function(){const b=document.querySelector(".password-toggle"),p=document.getElementById("login-password");b.addEventListener("click",function(){const show=p.type==="password";p.type=show?"text":"password";b.setAttribute("aria-pressed",String(show));b.setAttribute("aria-label",show?"Скрыть пароль":"Показать пароль");b.querySelector(".eye-slash").style.display=show?"none":""})})();</script>';
    echo '</div><div class="login-art-bottom" aria-hidden="true"></div></main></body></html>';
    exit;
}
$_SESSION['last_seen'] = time();
// All wedding media remains outside the webroot. Only authenticated organizers
// can load a gallery photo or an uploaded guest photo (including pending).
if(isset($_GET['media'])){
    if(($_SERVER['REQUEST_METHOD']??'GET')!=='GET'){
        http_response_code(405);exit;
    }
    $kind=(string)$_GET['media'];
    $id=(string)($_GET['id']??'');
    if(!in_array($kind,['gallery','guest'],true)||
       !preg_match('/^[a-f0-9-]{36}$/',$id)){
        http_response_code(404);exit;
    }
    try{
        require_once $private.'/backend/src/core.php';
        $db=\Wedding\db();
        if($kind==='gallery'){
            $entry=\Wedding\one($db,'SELECT filename FROM gallery_assets WHERE id=?',[$id]);
            $dir=$private.'/gallery-media';
        }else{
            $entry=\Wedding\one($db,'SELECT filename FROM photos WHERE id=?',[$id]);
            $dir=$private.'/uploads';
        }
        if(!$entry||!preg_match('/^[a-f0-9-]{36}\.jpg$/',(string)$entry['filename'])){
            http_response_code(404);exit;
        }
        $path=$dir.'/'.$entry['filename'];
        if(!is_file($path)||!is_readable($path)){
            http_response_code(404);exit;
        }
        header('Content-Type: image/jpeg');
        header('Content-Length: '.filesize($path));
        header('Cache-Control: private, no-store');
        readfile($path);
    }catch(Throwable $e){
        error_log('Wedding protected media error: '.$e->getMessage());
        http_response_code(503);
    }
    exit;
}
// Private organizer data API shares this already-authenticated admin session.
// Guest-facing API remains disabled and is never reachable through this gateway.
if (isset($_GET['api'])) {
    header('Content-Type: application/json; charset=UTF-8', true);
    $route = (string)($_GET['api'] ?? '');
    $method = (string)($_SERVER['REQUEST_METHOD'] ?? 'GET');
    if ($route === 'auth/session' && $method === 'GET') {
        echo json_encode(['ok'=>true,'role'=>'admin','csrf'=>(string)$_SESSION['csrf']],
          JSON_UNESCAPED_UNICODE | JSON_THROW_ON_ERROR);
        exit;
    }
    if (!preg_match('~^admin/[a-z][a-z0-9/-]{0,70}$~', $route) ||
        !in_array($method, ['GET','POST','PATCH'], true)) {
        http_response_code(404);
        echo '{"ok":false,"error":"not_found"}';
        exit;
    }
    $origin = (string)($_SERVER['HTTP_ORIGIN'] ?? '');
    if ($origin !== '') {
        $parts = parse_url($origin);
        if (!is_array($parts) ||
            ($parts['scheme'] ?? '') !== 'https' ||
            !in_array(strtolower((string)($parts['host'] ?? '')),
                ['nikitakristina.ru','www.nikitakristina.ru'], true)) {
            http_response_code(403);
            echo '{"ok":false,"error":"bad_origin"}';
            exit;
        }
    }
    if ($method !== 'GET') {
        $csrfToken = (string)($_SERVER['HTTP_X_CSRF_TOKEN'] ?? '');
        if ($csrfToken === '' || !hash_equals((string)$_SESSION['csrf'], $csrfToken)) {
            http_response_code(403);
            echo '{"ok":false,"error":"csrf"}';
            exit;
        }
    }
    try {
        $backend = $private.'/backend/src/api.php';
        if (!is_file($backend)) throw new RuntimeException('Backend not installed');
        // Fail closed rather than echoing PHP source if a broken deployment
        // accidentally removes the opening PHP tag.
        $prefix = file_get_contents($backend, false, null, 0, 5);
        if ($prefix !== '<?php') throw new RuntimeException('Malformed backend PHP entrypoint');
        require_once $backend;
        $database = \Wedding\db();
        \Wedding\adminRoute($database, $login, $route, $method, \Wedding\config());
    } catch (Throwable $error) {
        error_log('Wedding admin API error: '.$error->getMessage());
        http_response_code(503);
        echo '{"ok":false,"error":"admin_backend_unavailable","message":"База данных временно недоступна"}';
        exit;
    }
}
$types = [
    'index.html' => 'text/html; charset=UTF-8',
    'src/admin-app.js' => 'text/javascript; charset=UTF-8',
    'src/admin-toast.js' => 'text/javascript; charset=UTF-8',
    'src/admin-data-ui.js' => 'text/javascript; charset=UTF-8',
    'src/admin-program.js' => 'text/javascript; charset=UTF-8',
    'src/admin-settings.js' => 'text/javascript; charset=UTF-8',
    'src/admin-photos.js' => 'text/javascript; charset=UTF-8',
    'src/venue-files-ui.js' => 'text/javascript; charset=UTF-8',
    'src/admin-guests.js' => 'text/javascript; charset=UTF-8',
    'src/data.js' => 'text/javascript; charset=UTF-8',
    'src/venues.js' => 'text/javascript; charset=UTF-8',
    'src/venues-data.js' => 'text/javascript; charset=UTF-8',
    'src/venue-detail-ui.js' => 'text/javascript; charset=UTF-8',
    'src/venues-pricing.js' => 'text/javascript; charset=UTF-8',
    'src/venue-evaluation.js' => 'text/javascript; charset=UTF-8',
    'src/venue-transcript-costs.js' => 'text/javascript; charset=UTF-8',
    'src/venue-budget-coverage.js' => 'text/javascript; charset=UTF-8',
    'src/venues-photos-1.js' => 'text/javascript; charset=UTF-8',
    'src/venues-photos-2.js' => 'text/javascript; charset=UTF-8',
    'src/venues-photos-3.js' => 'text/javascript; charset=UTF-8',
    'src/venues-photos-4.js' => 'text/javascript; charset=UTF-8',
    'src/venues-photos-5.js' => 'text/javascript; charset=UTF-8',
    'src/styles.css' => 'text/css; charset=UTF-8',
    'src/venues.css' => 'text/css; charset=UTF-8',
    'src/venue-detail-ui.css' => 'text/css; charset=UTF-8',
    'src/admin-data.css' => 'text/css; charset=UTF-8',
    'src/admin-program.css' => 'text/css; charset=UTF-8',
    'src/admin-photos.css' => 'text/css; charset=UTF-8',
    'src/venue-files-ui.css' => 'text/css; charset=UTF-8',
    'src/admin-guests.css' => 'text/css; charset=UTF-8',
    'src/admin-heading.css' => 'text/css; charset=UTF-8',
];
$asset = $_GET['asset'] ?? 'index.html';
if (!is_string($asset) || !isset($types[$asset])) {
    http_response_code(404);
    exit;
}
$path = $private.'/admin-release/'.$asset;
if (!is_file($path) || !is_readable($path)) {
    http_response_code(503);
    header('Content-Type: text/plain; charset=UTF-8', true);
    exit('Admin bundle unavailable');
}
header('Content-Type: '.$types[$asset], true);
readfile($path);
